previewCss:
.darma-loader-darma-b16-magnet-filings { --accent: var(--loader-color, #dc2626); --accent-2: var(--loader-secondary-color, #3b82f6); width: var(--loader-size, 118px); height: calc(var(--loader-size, 118px) * .78); position: relative; }
.darma-loader-darma-b16-magnet-filings .darma-loader-darma-b16-magnet-filings__bar { position: absolute; left: 28%; top: 44%; width: 44%; height: 12%; border-radius: 3px; background: linear-gradient(90deg, var(--accent) 50%, var(--accent-2) 50%); }
.darma-loader-darma-b16-magnet-filings span { position: absolute; border-radius: 50%; box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent); animation: darma-loader-darma-b16-magnet-filings-mag-field calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
.darma-loader-darma-b16-magnet-filings span:nth-of-type(1) { left: 28%; top: 35%; width: 44%; height: 30%; }
.darma-loader-darma-b16-magnet-filings span:nth-of-type(2) { left: 19%; top: 27%; width: 62%; height: 46%; animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b16-magnet-filings span:nth-of-type(3) { left: 10%; top: 19%; width: 80%; height: 62%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b16-magnet-filings span:nth-of-type(4) { left: 1%; top: 10%; width: 98%; height: 80%; animation-delay: calc(var(--loader-speed, 1s) * .66); }
@keyframes darma-loader-darma-b16-magnet-filings-mag-field { 0%, 100% { box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent); transform: scale(.96); } 42% { box-shadow: 0 0 0 3px var(--accent-2); transform: scale(1); } }

